import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivityService } from '@core/services/activity.service';
import {
    Activity,
    ActivityFilters,
    ActivityType,
    ACTIVITY_ICONS,
    ACTIVITY_LABELS
} from '@core/models/activity.model';
import { ConfigService } from '@services/config.service';
import { IconComponent } from '@components/ui/icon/icon.component';
import { ActivityDetailsModalComponent } from '@modals/activity-details-modal/activity-details-modal.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-activities',
    standalone: true,
    imports: [CommonModule, FormsModule, IconComponent, TranslateModule, ActivityDetailsModalComponent],
    templateUrl: './activities.component.html',
    styleUrl: './activities.component.css'
})
export class ActivitiesComponent implements OnInit, OnDestroy {
    activities: Activity[] = [];
    loading = false;

    // Pagination
    currentPage = 1;
    itemsPerPage = 50;
    totalCount = 0;
    totalPages = 0;

    // Filters
    filters: ActivityFilters = {};
    filterType: ActivityType | '' = '';
    filterStatus: 'pending' | 'success' | 'failed' | '' = '';
    filterAddress = '';
    filterToken = '';
    filterNetwork: number | '' = '';
    filterDateFrom = '';
    filterDateTo = '';
    searchQuery = '';

    // UI State
    selectedActivity: Activity | null = null;
    showDetailsModal = false;

    // Constants
    activityTypes: ActivityType[] = [
        'CREATE_LOCK',
        'ADD_TO_LOCK',
        'UNLOCK',
        'CHANGE_OWNER',
        'ADD_SIGNER',
        'REMOVE_SIGNER',
        'BATCH_UPDATE_SIGNERS',
        'UPDATE_THRESHOLD',
        'RESCUE_TOKEN',
        'APPROVE_OPERATION',
        'EXECUTE_OPERATION',
        'TRANSFER_ETH',
        'TRANSFER_TOKEN'
    ];

    activityIcons = ACTIVITY_ICONS;
    activityLabels = ACTIVITY_LABELS;

    constructor(
        private activityService: ActivityService,
        private configService: ConfigService,
        private translate: TranslateService, private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[ActivitiesComponent] initialized');
        this.loadActivities();
    }

    async loadActivities() {
        this.loading = true;
        try {
            const offset = (this.currentPage - 1) * this.itemsPerPage;
            this.activities = await this.activityService.getActivities(
                this.buildFilters(),
                this.itemsPerPage,
                offset
            );
            this.totalCount = await this.activityService.getTotalCount(this.buildFilters());
            this.totalPages = Math.ceil(this.totalCount / this.itemsPerPage);
        } catch (e) {
            this.logger.error('Failed to load activities:', e);
        } finally {
            this.loading = false;
        }
    }

    buildFilters(): ActivityFilters {
        const filters: ActivityFilters = {};

        if (this.filterType) filters.type = this.filterType;
        if (this.filterStatus) filters.status = this.filterStatus;
        if (this.filterAddress) filters.address = this.filterAddress;
        if (this.filterToken) filters.token = this.filterToken;
        if (this.filterNetwork) filters.chainId = Number(this.filterNetwork);
        if (this.filterDateFrom) filters.dateFrom = new Date(this.filterDateFrom).getTime();
        if (this.filterDateTo) filters.dateTo = new Date(this.filterDateTo).getTime();
        if (this.searchQuery) filters.searchQuery = this.searchQuery;

        return filters;
    }

    applyFilters() {
        this.currentPage = 1;
        this.loadActivities();
    }

    clearFilters() {
        this.filterType = '';
        this.filterStatus = '';
        this.filterAddress = '';
        this.filterToken = '';
        this.filterNetwork = '';
        this.filterDateFrom = '';
        this.filterDateTo = '';
        this.searchQuery = '';
        this.applyFilters();
    }

    onSearch() {
        this.applyFilters();
    }

    goToPage(page: number) {
        if (page >= 1 && page <= this.totalPages) {
            this.currentPage = page;
            this.loadActivities();
        }
    }

    changeItemsPerPage(value: number) {
        this.itemsPerPage = value;
        this.currentPage = 1;
        this.loadActivities();
    }

    openDetails(activity: Activity) {
        this.selectedActivity = activity;
        this.showDetailsModal = true;
    }

    closeDetails() {
        this.showDetailsModal = false;
        this.selectedActivity = null;
    }

    getExplorerUrl(txHash: string): string {
        const baseUrl = this.configService.isProd
            ? 'https://etherscan.io'
            : 'https://sepolia.etherscan.io';
        return `${baseUrl}/tx/${txHash}`;
    }

    formatDate(timestamp: number): string {
        return new Date(timestamp).toLocaleString();
    }

    formatTimeAgo(timestamp: number): string {
        const seconds = Math.floor((Date.now() - timestamp) / 1000);

        if (seconds < 60) return this.translate.instant('ACTIVITIES.TIME_AGO.SECONDS', { seconds });
        const minutes = Math.floor(seconds / 60);
        if (minutes < 60) return this.translate.instant('ACTIVITIES.TIME_AGO.MINUTES', { minutes });
        const hours = Math.floor(minutes / 60);
        if (hours < 24) return this.translate.instant('ACTIVITIES.TIME_AGO.HOURS', { hours });
        const days = Math.floor(hours / 24);
        return this.translate.instant('ACTIVITIES.TIME_AGO.DAYS', { days });
    }

    formatAddress(address: string): string {
        if (!address) return '';
        return `${address.substring(0, 6)}...${address.substring(address.length - 4)}`;
    }

    async exportAsJSON() {
        try {
            const json = await this.activityService.exportActivities();
            const blob = new Blob([json], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `activities-${Date.now()}.json`;
            a.click();
            URL.revokeObjectURL(url);
        } catch (e) {
            this.logger.error('Export failed:', e);
        }
    }

    async exportAsCSV() {
        try {
            const allActivities = await this.activityService.getActivities(this.buildFilters(), 10000, 0);
            const csv = this.convertToCSV(allActivities);
            const blob = new Blob([csv], { type: 'text/csv' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `activities-${Date.now()}.csv`;
            a.click();
            URL.revokeObjectURL(url);
        } catch (e) {
            this.logger.error('Export failed:', e);
        }
    }

    private convertToCSV(activities: Activity[]): string {
        const headers = ['ID', 'Timestamp', 'Type', 'Status', 'Network', 'TxHash', 'Address', 'Gas Cost', 'Error'];
        const rows = activities.map(a => [
            a.id,
            new Date(a.timestamp).toISOString(),
            a.type,
            a.status,
            a.network || 'N/A',
            a.txHash || '',
            a.address,
            a.gasCost || '',
            a.error?.message || ''
        ]);

        return [headers, ...rows]
            .map(row => row.map(cell => `"${cell}"`).join(','))
            .join('\n');
    }

    getPaginationPages(): number[] {
        const pages: number[] = [];
        const maxVisible = 5;

        let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
        let end = Math.min(this.totalPages, start + maxVisible - 1);

        if (end - start < maxVisible - 1) {
            start = Math.max(1, end - maxVisible + 1);
        }

        for (let i = start; i <= end; i++) {
            pages.push(i);
        }

        return pages;
    }

    getNetworkName(chainId: number | undefined): string {
        if (!chainId) return this.translate.instant('ACTIVITIES.NETWORK.UNKNOWN');
        switch (chainId) {
            case 1:
                return this.translate.instant('ACTIVITIES.NETWORK.MAINNET');
            case 11155111:
                return this.translate.instant('ACTIVITIES.NETWORK.SEPOLIA');
            default:
                return this.translate.instant('ACTIVITIES.NETWORK.CHAIN', { id: chainId });
        }
    }

    getNetworkBadgeClass(chainId: number | undefined): string {
        if (!chainId) return 'bg-gray-100 text-gray-700';
        switch (chainId) {
            case 1:
                return 'bg-green-100 text-green-800';
            case 11155111:
                return 'bg-blue-100 text-blue-800';
            default:
                return 'bg-gray-100 text-gray-700';
        }
    }

    ngOnDestroy(): void {
        this.logger.debug('[ActivitiesComponent] destroyed');
    }
}
